#define MAX_STEPS 500        // Maximum raymarching iterations
#define MAX_DIST 100.0        // Maximum ray distance
#define SURF_DIST 0.1      // Surface detection threshold

// 25-31. Rotation utility function
mat2 rot(float a) {
    // 26. TWEAKABLE: Change tan() to sin() for less aggressive warping
    float c = sin(a * 0.1 + 0.1 * (a));         // Tangent for extreme warping
    // 27. TWEAKABLE: Add sin() or cos() for different rotation effects
    float s = sin(a * 0.01 + 5.0);            // Sine component
    return mat2(c, s, -s, c);// Modified rotation matrix
}

// 32-35. Color palette function
vec3 palette(float t) {
    // 34. TWEAKABLE: Modify coefficients for different color patterns
    return 0.5 + 0.5 * cos(1.28318 * (vec3(0.0, 0.522, 0.616) * t + vec3(0.847, 0.886, 0.894)));
}

// 36-44. Main SDF function - HIGHLY TWEAKABLE
float spiralTunnel(vec3 p) {
    // 38. TWEAKABLE: Modify twist intensity and speed
    float twist = sin(iTime * 0.4) * 0.5;    // Time-based twist
    p.xz *= rot(p.y * twist);                // Apply spiral rotation

    // 41. TWEAKABLE: Modify tunnel radius and shape
    float r = length(p.x) - 2.1;            // Basic tunnel shape
    // 42. TWEAKABLE: Modify wave frequency and amplitude
    r += sin(p.x * 0.0 + iTime) /  3.0;       // Wave deformation
    return r;
}

// 45-47. Scene mapping function
float map(vec3 pos) {
    return spiralTunnel(pos);                // Scene consists of tunnel only
}

// 48-69. Ray marching implementation
vec4 rayMarch(vec3 ro, vec3 rd) {
    float t = 0.0;            // Total distance traveled
    float d;                  // Current distance to surface
    vec3 col = vec3(0.0);    // Accumulated color

    // 54-64. Main raymarching loop
    for (int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + rd * t;
        d = map(p);

        if (d < SURF_DIST || t > MAX_DIST) break;

        // 61. TWEAKABLE: Modify color intensity and distribution
        float colorFactor = t * 0.005;
        col += palette(colorFactor) / (1.0 + d * 10.0);
        t += d;
    }

    // 66-67. TWEAKABLE: Modify surface highlighting and alpha
    if (d < SURF_DIST) col *= 0.85;           // Surface highlight
    return vec4(col, 1.0 - t * 1.1);        // Final color with alpha
}

// 70-80. Main image function
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // 72. Screen space calculation
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // 74-75. TWEAKABLE: Modify camera position and direction
    vec3 ro = vec3(0.6, 0.15, -30.0);         // Ray origin (camera position)
    vec3 rd = normalize(vec3(uv, 1.0));       // Ray direction

    // 77. TWEAKABLE: Modify camera rotation
    rd.zy *= rot(abs(iTime - 0.5));    // Camera rotation

    fragColor = rayMarch(ro, rd);             // Final render
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    vec2 center = vec2(0.5);

    float strength = 0.61;
    int iterations = 3;

    vec3 color = vec3(0.0);

    for (int i = 0; i < iterations; i++) {
        float t = float(i) / float(iterations);
        vec2 offset = (uv - center) * t * strength;
        color += texture(iChannel0, uv - offset).rgb;
    }

    color /= float(iterations);
    fragColor = vec4(color, 1.0);
}

